class Solution {public:
long long maxSum(vector<int>& nums,int k,int m){int n=nums.size(); const long long N=LLONG_MIN/4; vector<long long> p(n+1),prev(n+1,0),cur(n+1);for(int i=0;i<n;i++)p[i+1]=p[i]+nums[i];for(int j=1;j<=k;j++){fill(cur.begin(),cur.end(),N);long long best=N;for(int i=1;i<=n;i++){if(i>=m&&prev[i-m]!=N)best=max(best,prev[i-m]-p[i-m]);cur[i]=cur[i-1];if(best!=N)cur[i]=max(cur[i],p[i]+best);}prev.swap(cur);}return prev[n];}
};
